import json
from src.nodes.base import BaseNode
from src.runtime.architectural_features import (
    ArchitecturalPlan,
    get_architectural_feature_realizer,
)

class Hou_Mcp_Architecture_Realize(BaseNode):
    name = "hou_mcp_architecture_realize"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("plan_json", "string", widget_type="text", default="{}")
        self.add_output("realization_json")
        self.add_output("realized_count", "int")
        self.add_output("failed_count",   "int")
        self.add_output("production_ready", "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        raw_plan = (inputs.get("plan_json") or "{}").strip()
        try:
            plan_dict = json.loads(raw_plan)
            if not isinstance(plan_dict, dict):
                plan_dict = {}
        except Exception:
            plan_dict = {}

        try:
            plan   = ArchitecturalPlan.from_dict(plan_dict)
            result = get_architectural_feature_realizer().realize(plan)
            return {
                "realization_json": json.dumps(result.to_dict(), sort_keys=True, indent=2),
                "realized_count":   result.realized,
                "failed_count":     result.failed,
                "production_ready": result.ok,
                "exec_out":         True,
            }
        except Exception as exc:
            self.log_error(f"hou_mcp_architecture_realize failed: {exc}")
            return {
                "realization_json": "{}", "realized_count": 0,
                "failed_count": 0, "production_ready": False, "exec_out": True,
            }

def register_node():
    return Hou_Mcp_Architecture_Realize
